head.script:
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setVal = function() {
    scwin.simulateWrapper('#gridView1_column7', 'drag', {
        dx: -60,
        dy: 0
    });
}
scwin.checkVal = function() {
    return WebSquare.wUnit.getJq('.w2grid_columnMove_ghost').css('display') == 'block';
}
scwin.checkVal2 = function() {
    return WebSquare.wUnit.getJq('.w2grid_columnMove_ghost').text() == 'nam23e2';
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 1. Property 탭 또는 Source 탭에서 gridView1 의 columnMove 부분을 확인한다.
    //1. In the Property tab or Source tab, check the columnMove part of gridView1.
    //Verify step 1. columnMove = 'true'
    //Test step 2. 브라우저에서 columnMove 를 한다.
    //2. Do columnMove in the browser.
    //Verify step 2. A tooltip is created. (Tooltips are not created in previous versions)
    WebSquare.wUnit.addCommand("set", "scwin.setVal()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //		dataList1.setJSON([]);
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 27-Apr-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
